using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Microsoft.Extensions.DependencyInjection; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeQueryRegistrationTests{[Fact]public void Registration_once_and_twice_is_idempotent(){var s=new ServiceCollection();s.AddAstronomyKnowledgeQueryModel();s.AddAstronomyKnowledgeQueryModel();Assert.Single(s.Where(d=>d.ServiceType==typeof(IAstronomyKnowledgeQueryValidator)));using var p=s.BuildServiceProvider();Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeQueryValidator>());var c1=p.GetRequiredService<IAstronomyKnowledgeCatalog>();var c2=p.GetRequiredService<IAstronomyKnowledgeCatalog>();Assert.Same(c1,c2);Assert.Empty(s.Where(d=>d.ServiceType.Name.Contains("QueryEngine",StringComparison.Ordinal)));}[Fact]public void Null_services_rejected(){Assert.Throws<ArgumentNullException>(()=>AstronomyKnowledgeQueryRegistrationExtensions.AddAstronomyKnowledgeQueryModel(null!));}}
